<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); DB::statement("CREATE TABLE IF NOT EXISTS cash_transfers (id UUID PRIMARY KEY, from_branch_id UUID NULL REFERENCES branches(id) ON DELETE SET NULL, to_branch_id UUID NULL REFERENCES branches(id) ON DELETE SET NULL, amount DECIMAL(12,2) NOT NULL, status VARCHAR(255) DEFAULT 'completed', transfer_date TIMESTAMP NOT NULL, notes TEXT NULL, created_by UUID NULL REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMP NULL, updated_at TIMESTAMP NULL);"); echo "Table created";
